      after,
      before[beforeIndex],
      afterIndex,
      LOOK_AHEAD,
    );
    const nextBeforeAnchor = findNearby(
      before,
      after[afterIndex],
      beforeIndex,
      LOOK_AHEAD,
    );

    const afterDistance =
      nextAfterAnchor < 0
        ? Number.POSITIVE_INFINITY
        : nextAfterAnchor - afterIndex;
    const beforeDistance =
      nextBeforeAnchor < 0
        ? Number.POSITIVE_INFINITY
        : nextBeforeAnchor - beforeIndex;

