export async function loadFolioContentSnapshotFromIdb(
  folioId: string,
): Promise<FolioContentSnapshot | null> {
  if (!isBrowser()) return null;
  try {
    return await tx("folio-content", "readwrite", async (t) => {
      const store = t.objectStore("folio-content");
      const rec = await reqAsPromise<FolioContentSnapshot | undefined>(store.get(folioId));
      if (!rec) return null;
      if (rec.typstSource === undefined) {
        rec.typstSource = htmlToTypst(rec.html);
        rec.format = "typst";
        await reqAsPromise(store.put(rec));
      }
      return rec;
    });
  } catch {
    return null;
  }
}

export const FOLIO_CONTENT_SAVED = "twyne:folio-content-saved";

async function updateFolioContent(
  folioId: string,
  update: (previous: FolioContentSnapshot | undefined) => FolioContentSnapshot,
): Promise<void> {
  if (!isBrowser()) return;
  const rec = await tx("folio-content", "readwrite", async (t) => {
    const store = t.objectStore("folio-content");
    const previous = await reqAsPromise<FolioContentSnapshot | undefined>(store.get(folioId));
    const next = update(previous);
    await reqAsPromise(store.put(next));
    return next;
  });
  window.dispatchEvent(new CustomEvent(FOLIO_CONTENT_SAVED, { detail: rec }));
}

export async function saveFolioContentToIdb(folioId: string, html: string): Promise<void> {
  await updateFolioContent(folioId, (previous) => ({
    folioId, html, format: "typst",
    typstSource: previous?.typstSource !== undefined
      ? (previous.html === html ? previous.typstSource : reconcileTypstSource(previous.typstSource, html))
      : htmlToTypst(html),
    updatedAt: previous?.html === html ? previous.updatedAt : Date.now(),
  }));
}

/** Save source and its visual projection as one recoverable document. */
export async function saveFolioTypstToIdb(folioId: string, source: string, html?: string, expectedSource?: string): Promise<void> {
  await updateFolioContent(folioId, (previous) => {
    if (expectedSource !== undefined && previous?.typstSource !== expectedSource) throw new Error("The manuscript changed while this source was being edited. Review the latest source before applying.");
    return ({
    folioId, html: html ?? typstToHtml(source), format: "typst", typstSource: source,
    updatedAt: previous?.typstSource === source ? previous.updatedAt : Date.now(),
    });
  });
}

/** Sync installs the remote revision stamp instead of inventing a local edit. */
export async function saveFolioContentSnapshotToIdb(snapshot: FolioContentSnapshot): Promise<void> {
  await updateFolioContent(snapshot.folioId, (previous) => ({
    ...snapshot,
    format: "typst",
    typstSource: snapshot.typstSource ?? (previous?.typstSource !== undefined
      ? reconcileTypstSource(previous.typstSource, snapshot.html)
      : htmlToTypst(snapshot.html)),
  }));
}

